{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 쿼리의 지연 원인을 근거로 좁히고, 원인에 맞는 변경을 적용한 뒤 전후 수치로 효과를 확인했는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면에서 신고 목록 조회에 3.2초가 걸렸던 상황과 해당 조회의 조건을 설명한다.",
          "task": "본인이 맡은 조회 성능 개선 범위와 확인해야 했던 지연 원인을 설명한다.",
          "action": "실행 계획, 로그 또는 호출 구조에서 확인한 병목의 근거를 제시하고, 인덱스 추가와 조인 정리가 그 원인에 어떻게 대응했는지 설명한다.",
          "result": "변경 전후의 측정 조건과 응답 시간을 제시하고, 3.2초에서 0.4초로 줄었다는 결과를 어떻게 확인했는지 설명한다."
        },
        "expectedEvidence": [
          "실행 계획, 로그 또는 호출 구조에서 확인한 사실과 쿼리 지연 원인 사이의 연결",
          "추가한 인덱스와 수정한 조인 내용, 해당 변경이 병목을 줄이는 이유",
          "본인이 직접 수행한 분석 및 변경 작업의 범위",
          "개선 전후 응답 시간과 측정 방법, 비교 조건의 일관성"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄일 때, 원인을 찾은 과정과 직접 바꾼 내용, 변경 후 확인 과정을 말씀해 주세요.",
      "answerTip": "경험을 시간순으로 정리해 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획, 로그 또는 호출 구조에서 확인한 내용을 근거로 지연 원인을 구체적으로 설명한다.",
            "본인이 추가한 인덱스와 조인 수정 내용을 구분하고, 각 변경이 확인된 병목에 적합한 이유를 설명한다.",
            "개선 전후의 응답 시간을 제시하며, 측정 방법과 비교 조건을 설명해 개선 효과를 수치로 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "지연 원인과 이를 확인한 근거를 일부 설명하지만, 관찰한 내용과 원인의 연결이 충분히 구체적이지 않다.",
            "인덱스 추가나 조인 수정 등 본인의 변경 작업은 확인되지만, 변경 내용이나 선택 이유의 설명이 부족하다.",
            "전후 응답 시간은 제시하지만 측정 방법이나 비교 조건을 충분히 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "지연 원인을 추정만 하거나 실행 계획, 로그, 호출 구조 등에서 확인한 근거를 제시하지 못한다.",
            "인덱스나 조인을 바꿨다는 설명에 그쳐 본인의 작업과 병목 개선의 연결을 확인하기 어렵다.",
            "개선 전후 수치나 확인 과정을 제시하지 못해 성능 개선 효과를 판단하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 알림 중복 발송을 로그와 운영 지표로 추적해 원인을 좁히고, 서비스 복구 조치와 재발 방지 조치를 구분해 수행했는지 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 배포 다음 날 같은 알림이 두 번 발송된다는 문의를 받은 상황을 설명한다.",
          "task": "중복 발송 원인을 파악하고 반복 발송을 멈추기 위해 본인이 맡은 역할을 설명한다.",
          "action": "시간순 로그와 확인 가능한 발송·실행 지표를 통해 원인을 좁힌 과정을 설명하고, 두 서버의 스케줄러 동시 실행에 대한 복구 조치와 잠금 적용 및 체크리스트 반영의 목적을 구분한다.",
          "result": "조치 후 중복 발송이 해소됐는지 확인한 근거와, 이후 배포에서 같은 문제가 반복되지 않도록 확인한 내용을 설명한다."
        },
        "expectedEvidence": [
          "시간대와 서버별 로그, 발송 건수 또는 실행 횟수 등 실제 확인한 자료를 통한 중복 실행 추적 과정",
          "클라이언트 문제라는 초기 추정에서 두 서버의 스케줄러 동시 실행으로 원인을 좁힌 근거",
          "당장의 중복 발송을 멈추거나 서비스를 정상화하기 위해 본인이 수행한 조치와 확인 내용",
          "잠금 적용과 배포 체크리스트 반영이 같은 원인의 재발을 막는 방식",
          "조치 이후 로그나 발송·실행 지표로 중복 발송 해소 여부를 확인한 결과"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림이 두 번 발송됐을 때, 문제를 처음 확인한 시점부터 조치 이후까지 본인이 진행한 과정을 말씀해 주세요.",
      "answerTip": "당시 경험을 차근차근 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그의 시간·서버 정보와 발송 또는 실행 지표를 연결해 초기 추정을 검토하고, 스케줄러 동시 실행으로 원인을 좁힌 과정을 설명한다.",
            "본인이 수행한 즉시 복구 조치와 잠금 적용·체크리스트 반영의 재발 방지 목적을 구분하고, 각 조치가 원인에 대응하는 방식을 설명한다.",
            "조치 후 로그나 발송·실행 지표로 중복 발송 해소를 확인한 결과와 이후 재발 여부를 확인한 내용을 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그를 통해 두 서버의 동시 실행을 확인했다고 설명하지만, 추적 과정이나 함께 확인한 지표의 설명이 부족하다.",
            "복구 및 재발 방지와 관련된 본인의 조치는 확인되지만, 즉시 정상화와 반복 방지의 목적 구분이나 작동 방식이 불명확하다.",
            "조치 후 정상화 여부는 설명하지만, 이를 확인한 자료나 이후 재발 여부의 확인 과정이 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "중복 발송 원인을 단정할 뿐 로그나 운영 자료를 통해 원인을 좁힌 근거를 제시하지 못한다.",
            "잠금 적용이나 체크리스트 반영을 언급하더라도 본인의 조치, 복구 과정, 재발 방지 방식이 확인되지 않는다.",
            "조치 이후 중복 발송이 해소됐는지 확인한 근거를 제시하지 못하거나 질문과 무관한 개발 경험을 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "세탁소 인터뷰에서 수집한 요청의 목적을 파악하고, 포함·제외 범위와 우선순위, 예외 케이스를 요구사항 정의서로 구체화하여 구현 범위를 합의할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 인터뷰에서 어떤 요청이 나왔으며, 요청을 그대로 구현하기 어려웠던 이유나 정리가 필요했던 배경을 설명한다.",
          "task": "예약 서비스가 해결할 문제를 정하고, 팀에서 구현할 기능의 범위를 요구사항 정의서로 정리해야 했던 본인의 역할을 설명한다.",
          "action": "요청의 목적을 확인하고 기능별로 정리한 뒤, 포함·제외 항목과 우선순위, 예외 케이스를 문서화하여 개발 담당 팀원과 검토하고 조정한 과정을 설명한다.",
          "result": "최종적으로 합의한 구현 범위와 제외·보류 항목을 제시하고, 합의 내용이 요구사항 정의서에 어떻게 반영되었는지 설명한다."
        },
        "expectedEvidence": [
          "인터뷰 요청을 서비스에서 해결할 문제와 연결하여 해석한 사례",
          "이번 구현에 포함한 항목과 제외하거나 보류한 항목 및 구분 이유",
          "기능의 우선순위를 정한 근거",
          "요구사항 정의서에 기록한 예외 케이스와 처리 방침",
          "개발 담당 팀원과 범위를 검토·조정한 과정 및 최종 합의의 문서 반영 내용"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소의 요청을 요구사항 정의서로 옮기고, 개발 담당 팀원과 구현 범위를 정한 과정을 설명해 주세요.",
      "answerTip": "당시 과정을 순서대로 이야기해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 인터뷰 요청과 해결할 문제를 연결하고, 포함·제외 범위와 우선순위의 근거를 구체적으로 설명한다.",
            "요구사항 정의서에 담은 예외 케이스와 처리 방침을 실제 사례로 설명한다.",
            "본인이 개발 담당 팀원과 범위를 검토·조정한 행동, 최종 합의 내용, 문서 반영 결과가 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요청의 목적과 구현 범위를 정리한 사례는 확인되지만, 포함·제외 이유나 우선순위의 근거 중 일부가 불분명하다.",
            "예외 케이스의 문서화 또는 개발 담당 팀원과의 범위 합의가 일부 확인되지만, 처리 방침이나 최종 문서 반영 내용이 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "요청을 수집하거나 나열한 설명에 그쳐, 해결할 문제와 구현 범위를 어떻게 정했는지 확인하기 어렵다.",
            "우선순위, 예외 케이스, 범위 합의에 관한 설명이 대부분 없거나, 본인의 행동과 최종 정리 결과를 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예약·취소·알림 기능을 화면 흐름으로 연결하고, 화면 상태와 예외 처리, 안내 문구를 구현자가 이해할 수 있도록 화면설계서에 구체화할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약·취소·알림 중 선택한 기능의 이용 흐름과 화면설계가 필요했던 상황을 설명한다.",
          "task": "해당 기능의 화면 이동, 상태 변화, 예외 처리와 안내 내용을 Figma 화면설계서에 담아야 했던 본인의 역할을 설명한다.",
          "action": "사용자 동작에 따른 화면 이동과 상태 변화를 정의하고, 정상 흐름에서 벗어나는 상황의 처리 방식과 안내 문구를 화면 또는 주석으로 표현한 방법을 설명한다.",
          "result": "완성된 화면설계서의 구체적인 내용을 제시하고, 이를 통해 구현자가 어떤 화면과 동작을 만들어야 하는지 확인할 수 있게 된 결과를 설명한다."
        },
        "expectedEvidence": [
          "선택한 기능의 시작부터 완료까지 화면 이동과 사용자 동작의 연결",
          "사용자 동작이나 처리 결과에 따른 화면 요소의 상태 변화 및 전환 조건",
          "예외 상황의 발생 조건과 이후 처리 또는 이동 경로",
          "상황별 안내 문구와 동작을 화면설계서에 명시한 구체적인 표현 방식"
        ]
      },
      "question": "동네 세탁소 예약 서비스의 예약·취소·알림 화면 중 하나를 골라, 이용 중 생길 수 있는 상황을 Figma 화면설계서에 어떻게 담았는지 설명해 주세요.",
      "answerTip": "한 가지 사례를 떠올려 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "선택한 기능의 화면 이동과 사용자 동작을 연결하고, 화면 요소의 상태가 바뀌는 조건을 구체적으로 설명한다.",
            "예외 상황의 발생 조건, 처리 방식, 이후 이동 경로와 안내 문구를 실제 설계 사례로 설명한다.",
            "화면이나 주석에 이를 어떻게 표현했는지 제시하여, 구현할 화면과 동작을 답변만으로도 파악할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "기본 화면 흐름과 일부 상태 변화 또는 예외 처리의 설계 사례가 확인된다.",
            "화면설계서에 담은 내용은 설명하지만, 상태 전환 조건, 예외 이후 경로, 안내 문구 중 일부가 빠져 구현 내용을 파악하려면 추가 확인이 필요하다."
          ]
        },
        "poor": {
          "criteria": [
            "Figma 사용이나 화면 수만 설명하여, 기능의 화면 흐름과 사용자 동작의 연결을 확인하기 어렵다.",
            "상태 변화, 예외 처리, 안내 문구를 설계한 구체적인 내용이 대부분 없거나 실제 화면설계서에 어떻게 담았는지 설명하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
